desafio.solucao:
/* estilo.css */
:root {
  --cor-texto: #1f2937;
  --cor-fundo: #ffffff;
  --cor-acento: #4f46e5;
  --espaco: 16px;
  --borda: 1px solid #e5e7eb;
}

body {
  font-family: system-ui, sans-serif;
  color: var(--cor-texto);
  background: var(--cor-fundo);
  line-height: 1.6;
  margin: 0 auto;
  max-width: 60ch;          /* largura confortável de leitura */
  padding: var(--espaco);
}

a { color: var(--cor-acento); }

.menu {
  display: flex;
  gap: var(--espaco);
  padding: 0;
  list-style: none;
}

.artigo {
  border: var(--borda);
  padding: var(--espaco);
  margin-bottom: var(--espaco);
}

.artigo h2 { margin-top: 0; }

/*
  o teste: troque --cor-acento por #b91c1c e recarregue.
  os links e tudo que usa o acento mudam de uma vez.

  max-width com a unidade ch é largura em caracteres: 60ch é mais ou menos
  60 letras por linha, que é a faixa em que ler cansa menos.
*/

