* { box-sizing: border-box; }

.lista {
  display: flex;
  gap: 16px;                 /* espaço entre os cartões, sem margem */
  padding: 16px;
}

.cartao {
  width: 220px;              /* com border-box, é a largura final mesmo */
  padding: 16px;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  background: #fff;
}

.cartao h3 {
  margin-top: 0;             /* mata a margem de cima que o h3 traz de fábrica */
}

/*
  no F12 > Computed, o desenho da caixa mostra:
    content 186 x N     (220 menos os 16 de padding de cada lado e a borda)
    padding 16
    border  1
    margin  0

  se você tirar o border-box, o mesmo cartão passa a ocupar 254px e os três
  deixam de caber. Foi por isso que essa linha virou padrão de projeto.
*/

