/* galeria que se ajusta sozinha */
.galeria {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}
/* lê-se: quantas colunas couberem, cada uma com no mínimo 220px,
   dividindo o espaço que sobrar por igual */

/* três colunas fixas, a do meio maior */
.tres {
  display: grid;
  grid-template-columns: 1fr 2fr 1fr;
  gap: 16px;
}

/* layout de página com áreas com nome */
.pagina {
  display: grid;
  grid-template-columns: 220px 1fr;
  grid-template-areas:
    "cabecalho cabecalho"
    "lateral   conteudo"
    "rodape    rodape";
  gap: 16px;
  min-height: 100vh;
}

.pagina > header { grid-area: cabecalho; }
.pagina > nav    { grid-area: lateral; }
.pagina > main   { grid-area: conteudo; }
.pagina > footer { grid-area: rodape; }

desafio.solucao:
* { box-sizing: border-box; }

/* 1. a galeria, sem media query */
.galeria {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 16px;
  padding: 16px;
}

.galeria article {
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  padding: 16px;
}

/*
  com 260px de mínimo:
  janela de 900px  -> 3 colunas
  janela de 600px  -> 2 colunas
  janela de 400px  -> 1 coluna
  quem decide é a conta, não uma faixa que você escolheu na unha.
*/

/* 2. o esqueleto da página */
.pagina {
  display: grid;
  grid-template-columns: 220px 1fr;
  grid-template-areas:
    "cabecalho cabecalho"
    "lateral   conteudo"
    "rodape    rodape";
  gap: 16px;
  min-height: 100vh;
}

.pagina > header { grid-area: cabecalho; }
.pagina > nav    { grid-area: lateral; }
.pagina > main   { grid-area: conteudo; }
.pagina > footer { grid-area: rodape; }

/* no celular, uma coluna só: o desenho muda, o HTML não */
@media (max-width: 640px) {
  .pagina {
    grid-template-columns: 1fr;
    grid-template-areas:
      "cabecalho"
      "conteudo"
      "lateral"
      "rodape";
  }
}

