/* 1. nada pode estourar a tela */
img, video { max-width: 100%; height: auto; }

/* 2. largura máxima, e não largura fixa */
.conteudo {
  max-width: 65ch;
  margin: 0 auto;
  padding: 16px;
}

/* 3. tipografia que acompanha a tela, com limite dos dois lados */
h1 { font-size: clamp(1.5rem, 4vw, 2.5rem); }
/* nunca menor que 1.5rem, nunca maior que 2.5rem, e no meio segue 4% da largura */

/* 4. mobile primeiro: o básico vale sempre, o extra vem depois */
.painel {
  display: grid;
  gap: 16px;
}

@media (min-width: 768px) {     /* daqui pra cima, duas colunas */
  .painel {
    grid-template-columns: 1fr 1fr;
  }
}

/* respeite quem pediu menos movimento */
@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
}

